// Generate personalized call script
const leadName = $json.leadName || 'there';
const propertyRef = $json.propertyRef || 'your recent inquiry';

// Create a natural, professional greeting
const script = `Hello ${leadName}! This is an automated call from ABC Realty regarding ${propertyRef}. 

We received your inquiry and wanted to follow up quickly. If you're interested in learning more, please press 1 now. 

If you'd like us to call you back at a better time, press 2. 

Or press 3 if you're no longer interested. 

Thank you for considering ABC Realty for your real estate needs!`;

// Clean script for TTS
const cleanScript = script
  .replace(/\n+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return {
  ...$json,
  callScript: cleanScript,
  scriptLength: cleanScript.length
};

// Structure the AI-extracted call info
const leadData = $('Set Call Result Data').item.json.leadData;
const callData = $('Set Call Result Data').item.json;
let aiOutput;

try {
  aiOutput = typeof $json.output === 'string' ? JSON.parse($json.output) : $json.output;
} catch (e) {
  aiOutput = {
    interestLevel: 'unknown',
    recommendedAction: 'Manual review required',
    qualificationNotes: 'AI parsing failed'
  };
}

// Map DTMF to interest
const dtmfInterestMap = {
  '1': 'high',
  '2': 'medium',
  '3': 'none',
  '0': 'unknown'
};

const dtmfResponse = callData.dtmfResponse || '0';
const dtmfInterest = dtmfInterestMap[dtmfResponse] || 'unknown';

// Use DTMF if available, otherwise use AI inference
const finalInterest = dtmfResponse !== '0' ? dtmfInterest : (aiOutput.interestLevel || 'unknown');

return {
  // Lead info
  leadName: leadData.leadName,
  leadPhone: leadData.leadPhone,
  leadEmail: leadData.leadEmail,
  propertyRef: leadData.propertyRef,

  // Call info
  callSid: callData.callSid,
  callStatus: callData.callStatus,
  dtmfResponse: dtmfResponse,
  callInitiatedAt: leadData.callInitiatedAt,

  // Qualification
  interestLevel: finalInterest,
  estimatedBudget: aiOutput.estimatedBudget || 'Not specified',
  timeline: aiOutput.timeline || 'Not specified',
  preferredContact: aiOutput.preferredContact || 'Phone',
  propertyRequirements: aiOutput.propertyRequirements || [],
  recommendedAction: aiOutput.recommendedAction || 'Follow up call',
  qualificationNotes: aiOutput.qualificationNotes || ''
};

// Calculate lead score for interested voice leads
const lead = $json.qualifiedLead;

let score = 0;
const scoreFactors = [];

// Interest level scoring
if (lead.interestLevel === 'high') {
  score += 40;
  scoreFactors.push({ factor: 'High Interest', points: 40 });
} else if (lead.interestLevel === 'medium') {
  score += 25;
  scoreFactors.push({ factor: 'Medium Interest', points: 25 });
}

// DTMF engagement bonus
if (lead.dtmfResponse === '1') {
  score += 15;
  scoreFactors.push({ factor: 'Active Engagement (Pressed 1)', points: 15 });
}

// Contact info completeness
if (lead.leadEmail) {
  score += 10;
  scoreFactors.push({ factor: 'Has Email', points: 10 });
}

// Timeline urgency
if (lead.timeline && lead.timeline.toLowerCase().includes('asap') || 
    lead.timeline && lead.timeline.toLowerCase().includes('immediate')) {
  score += 15;
  scoreFactors.push({ factor: 'Urgent Timeline', points: 15 });
} else if (lead.timeline && !lead.timeline.includes('Not specified')) {
  score += 5;
  scoreFactors.push({ factor: 'Has Timeline', points: 5 });
}

// Budget mentioned
if (lead.estimatedBudget && !lead.estimatedBudget.includes('Not specified')) {
  score += 10;
  scoreFactors.push({ factor: 'Budget Mentioned', points: 10 });
}

// Determine priority
let priority = 'Medium';
if (score >= 60) priority = 'Hot';
else if (score >= 40) priority = 'Warm';

return {
  ...lead,
  leadScore: score,
  priority: priority,
  scoreFactors: scoreFactors,
  scoredAt: new Date().toISOString()
};

